require __DIR__.'/../includes/bootstrap.php';require_login();verify_csrf();header('Content-Type: application/json');$data=json_decode(file_get_contents('php://input'),true);$items=$data['items']??[];$discount=max(0,(float)($data['discount']??0));$method=$data['payment_method']??'';$paid=(float)($data['amount_paid']??0);if(!$items||!in_array($method,['cash','card','qr'],true)){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Invalid checkout details.']);exit;}
$pdo=db();try{$pdo->beginTransaction();$resolved=[];$subtotal=0;foreach($items as $item){$id=(int)($item['id']??0);$qty=max(1,(int)($item['quantity']??0));$s=$pdo->prepare("SELECT id,name,sku,price,stock_quantity FROM products WHERE id=? AND status='active' FOR UPDATE");$s->execute([$id]);$p=$s->fetch();if(!$p)throw new RuntimeException('A product is no longer available.');if($qty>$p['stock_quantity'])throw new RuntimeException($p['name'].' only has '.$p['stock_quantity'].' left.');$total=(float)$p['price']*$qty;$subtotal+=$total;$resolved[]=[$p,$qty,$total];}$discount=min($discount,$subtotal);$grand=$subtotal-$discount;if($method!=='cash')$paid=$grand;if($paid+0.0001<$grand)throw new RuntimeException('Payment amount is less than the total.');$change=max(0,$paid-$grand);$receipt='POS-'.date('Ymd-His').'-'.random_int(100,999);$s=$pdo->prepare('INSERT INTO orders(receipt_number,cashier_id,subtotal,discount,grand_total,payment_method,amount_paid,change_amount) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$receipt,user()['id'],$subtotal,$discount,$grand,$method,$paid,$change]);$orderId=(int)$pdo->lastInsertId();$insert=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,sku,price,quantity,total) VALUES(?,?,?,?,?,?,?)');$stock=$pdo->prepare('UPDATE products SET stock_quantity=stock_quantity-? WHERE id=?');foreach($resolved as [$p,$qty,$total]){$insert->execute([$orderId,$p['id'],$p['name'],$p['sku'],$p['price'],$qty,$total]);$stock->execute([$qty,$p['id']]);}$pdo->commit();audit('checkout',$receipt);echo json_encode(['success'=>true,'order_id'=>$orderId,'receipt_number'=>$receipt]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();http_response_code(422);echo json_encode(['success'=>false,'message'=>$e instanceof RuntimeException?$e->getMessage():'Checkout could not be completed.']);}
